head.b:skin:
/*
 * Theme: Blogger Vệ Tinh Chuẩn SEO - Xanh Môi Trường
 * Designed for: Môi Trường Đô Thị Số 1 Quảng Ninh (thongtaccongquangninh.com)
 * Designed by: Antigravity
 */

/* CSS Variables - Design Tokens */
:root {
  --color-primary: #0B6E4F;      /* Xanh môi trường đậm, gợi sạch sẽ */
  --color-secondary: #F4A300;    /* Cam cảnh báo dùng cho CTA hotline */
  --color-primary-dark: #074b35;
  --color-bg-body: #ffffff;
  --color-bg-section: #f7f7f5;   /* Xám nhẹ tinh tế */
  --color-text-body: #1a1a1a;
  --color-text-meta: #5a5a5a;
  --font-family: 'Be Vietnam Pro', sans-serif;
}

/* Reset CSS */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: var(--font-family);
  background-color: var(--color-bg-section);
  color: var(--color-text-body);
  line-height: 1.7;
  font-size: 17px;
}
a { color: var(--color-primary); text-decoration: none; transition: all 0.3s ease; }
a:hover { color: var(--color-primary-dark); text-decoration: underline; }
img { max-width: 100%; height: auto; display: block; border-radius: 8px; }

/* Layout Containers */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Header Sticky */
header {
  background: var(--color-primary);
  color: white;
  padding: 15px 0;
  box-shadow: 0 4px 10px rgba(0,0,0,0.08);
  position: sticky;
  top: 0;
  z-index: 100;
}
.header-wrapper {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.logo h1 {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: -0.5px;
}
.logo h1 a {
  color: white;
}
.logo h1 a:hover {
  text-decoration: none;
}

/* Hotline Pulse Button màu Cam */
.header-hotline {
  background: var(--color-secondary);
  padding: 10px 20px;
  border-radius: 50px;
  font-weight: 700;
  font-size: 16px;
  box-shadow: 0 4px 15px rgba(244, 163, 0, 0.4);
  animation: pulse 1.5s infinite;
}
.header-hotline a {
  color: white;
}
@keyframes pulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.04); }
  100% { transform: scale(1); }
}

/* Main Content Area */
.main-wrapper {
  display: grid;
  grid-template-columns: 2.1fr 1fr;
  gap: 35px;
  margin: 40px auto;
}

/* Post Area */
.post-card {
  background: white;
  padding: 35px;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.03);
  margin-bottom: 30px;
}
.post-title {
  font-size: 28px;
  font-weight: 700;
  color: var(--color-primary);
  margin-bottom: 15px;
  line-height: 1.35;
}
.post-title a {
  color: var(--color-primary);
}
.post-title a:hover {
  color: var(--color-primary-dark);
  text-decoration: none;
}
.post-meta {
  font-size: 14px;
  color: var(--color-text-meta);
  margin-bottom: 25px;
  border-bottom: 1px solid #f0f0ee;
  padding-bottom: 10px;
}
.post-body {
  font-size: 17px;
  color: var(--color-text-body);
  text-align: justify;
}

/* Styling On-page HTML cho Bài viết */
.post-body h2 {
  font-size: 22px;
  color: var(--color-primary);
  margin: 35px 0 15px 0;
  border-left: 5px solid var(--color-secondary);
  padding-left: 15px;
  font-weight: 700;
}
.post-body h3 {
  font-size: 19px;
  color: var(--color-primary);
  margin: 25px 0 12px 0;
  font-weight: 600;
}
.post-body p {
  margin-bottom: 18px;
}
.post-body ul, .post-body ol {
  margin-bottom: 22px;
  padding-left: 20px;
}
.post-body li {
  margin-bottom: 10px;
}
.post-body strong {
  font-weight: 600;
  color: #000000;
}

/* Table styling chuẩn */
.post-body table {
  width: 100%;
  border-collapse: collapse;
  margin: 25px 0;
  font-size: 15px;
}
.post-body table th {
  background-color: var(--color-primary);
  color: white;
  font-weight: bold;
  padding: 12px;
  border: 1px solid #e5e7eb;
}
.post-body table td {
  padding: 12px;
  border: 1px solid #e5e7eb;
}
.post-body table tr:nth-child(even) {
  background-color: #fafafa;
}

/* Sidebar */
aside {
  display: flex;
  flex-direction: column;
  gap: 30px;
}
.widget-box {
  background: white;
  padding: 25px;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.03);
}
.widget-title {
  font-size: 18px;
  font-weight: 700;
  color: var(--color-primary);
  border-bottom: 2px solid #f0f0ee;
  padding-bottom: 12px;
  margin-bottom: 15px;
}

/* Widget NAP giống site mẹ */
.nap-box {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-dark) 100%);
  color: white;
  padding: 30px;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(11, 110, 79, 0.2);
}
.nap-box h3 {
  font-size: 18px;
  font-weight: 800;
  margin-bottom: 15px;
  border-bottom: 1px solid rgba(255,255,255,0.15);
  padding-bottom: 10px;
  letter-spacing: 0.5px;
}
.nap-box p {
  font-size: 14px;
  margin-bottom: 12px;
  line-height: 1.6;
  color: #e2f0ea;
}
.nap-btn {
  display: block;
  background: var(--color-secondary);
  color: white !important;
  text-align: center;
  padding: 12px;
  border-radius: 8px;
  font-weight: 700;
  margin-top: 15px;
  box-shadow: 0 4px 10px rgba(244, 163, 0, 0.3);
  text-decoration: none !important;
}

/* Footer */
footer {
  background: #111e18;
  color: #92a39a;
  padding: 40px 0;
  text-align: center;
  font-size: 14px;
  border-top: 5px solid var(--color-primary);
}
footer p {
  margin-bottom: 10px;
}
footer a {
  color: white;
  font-weight: 600;
}

/* Responsive */
@media (max-width: 768px) {
  .main-wrapper {
    grid-template-columns: 1fr;
    margin: 20px auto;
  }
  .header-wrapper {
    flex-direction: column;
    gap: 15px;
    text-align: center;
  }
  .post-card {
    padding: 20px;
  }
  .post-title {
    font-size: 22px;
  }
}

